#! /usr/bin/env dcli
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;
import 'package:dcli/dcli.dart';
import 'summarize-adaptive-workers.dart' as stats;
const worktree='/home/bsutton/git/.codex.workspaces/revault-issue-310-zip-read-performance';
const root='$worktree/docs/evidence/direct-clear-page-2026-10-12/raw';
void require(bool v,String m)=>stats.require(v,m);
Map<String,dynamic> paired(String label,List<Map<String,dynamic>> rows,{int? stratum}) {
 final rounds=[for(var r=2;r<14;r++)if(stratum==null||r%2==stratum)r];
 final logs=[for(final r in rounds)math.log(stats.number(rows.singleWhere((v)=>v['round']==r&&v['variant']=='new')['elapsed_seconds'],'new')/stats.number(rows.singleWhere((v)=>v['round']==r&&v['variant']=='old')['elapsed_seconds'],'old'))];
 final blocks=stratum==null?[for(var i=0;i<logs.length;i+=2)(logs[i]+logs[i+1])/2]:logs;
 require(blocks.length==6,'Six bootstrap blocks');final seed=stats.seedFor(label);final random=stats.Seeded(seed);
 final draws=List<double>.generate(10000,(_){var total=0.0;for(var n=0;n<6;n++)total+=blocks[random.nextInt(6)];return math.exp(total/6);})..sort();
 return {'geometric_mean_ratio':math.exp(logs.reduce((a,b)=>a+b)/logs.length),'low95':stats.percentile(draws,.025),'high95':stats.percentile(draws,.975),'pairs':rounds.length,'blocks':6,'replicates':10000,'seed':seed,'method':stratum==null?'six adjacent two-round paired log-ratio blocks':'six within-round-stratum paired log ratios'};
}
void main(){final output=File('$root/metrics-summary.json');require(!output.existsSync(),'Existing summary');final complete=stats.readObject('$root/paired-complete.json');require(complete['accepted']==112&&complete['identities_verified_after']==true&&complete['owned_agents_stopped']==true,'Incomplete');final identities=stats.readObject('$root/paired-identities.json');final executables=identities['variants'] as Map;final rows=File('$root/paired-samples.jsonl').readAsLinesSync().map((v)=>jsonDecode(v) as Map<String,dynamic>).toList();require(rows.length==112,'Exact112');final cases=(jsonDecode(File('$root/cases.json').readAsStringSync()) as List).cast<Map<String,dynamic>>();require(cases.length==2,'Two cases');final results=<Map<String,dynamic>>[];var guards=true;var useful=true;var usefulCohorts=0;for(var c=0;c<2;c++)for(var w=0;w<2;w++){final name=cases[c]['case'];final workflow=w==0?'single-file-interactive':'one-file-directory-bulkimport';final label='$name/$workflow';final selected=rows.where((r)=>r['case']==name&&r['workflow']==workflow).toList();require(selected.length==28,'Exact28 percohort'); final archiveSizes=selected.map((v)=>stats.number(v['archive_bytes'],'archive size')).toSet();require(archiveSizes.length==1&&archiveSizes.single>0,'Unchanged positive archive size across variants');for(var r=0;r<14;r++)for(var p=0;p<2;p++){final variant=(p+r+c+w)%2==0?'old':'new';final row=selected.singleWhere((v)=>v['round']==r&&v['position']==p);require(row['variant']==variant&&row['preparation']==(r<2)&&row['executable']==executables[variant],'Schedule/executable');require(row['persisted_bytes_mode_verified']==true&&row['cold_source']==true&&row['archive_and_output_drained_after_timing']==true,'Output gates');for(final key in ['elapsed_seconds','rss_bytes','user_seconds','system_seconds'])stats.number(row[key],key);require(row['source_sha256']==cases[c]['source_sha256'],'Source');}
final measured=selected.where((v)=>v['preparation']==false).toList();final elapsed=paired('$label/aggregate',measured);final views=[for(var p=0;p<2;p++)paired('$label/stratum$p',measured,stratum:p)];final variants=<String,dynamic>{};for(final variant in ['old','new']){final group=measured.where((v)=>v['variant']==variant).toList();final times=group.map((v)=>stats.number(v['elapsed_seconds'],'elapsed')).toList()..sort();final rss=group.map((v)=>stats.number(v['rss_bytes'],'rss')).toList()..sort();variants[variant]={'median_seconds':stats.percentile(times,.5),'maximum_rss_bytes':rss.last,'median_rss_bytes':stats.percentile(rss,.5),'every_rss_bytes':rss};}
final maxRatio=variants['new']['maximum_rss_bytes']/variants['old']['maximum_rss_bytes'];final medianRatio=variants['new']['median_rss_bytes']/variants['old']['median_rss_bytes'];final guard=elapsed['high95']<=1.05&&maxRatio<=1.05;guards=guards&&guard;if(name=='source-zstd-1gib'&&workflow=='single-file-interactive'){usefulCohorts++;useful=useful&&medianRatio<=.95;}results.add({'case':name,'workflow':workflow,'aggregate':elapsed,'round_strata':views,'variants':variants,'maximum_rss_ratio':maxRatio,'median_rss_ratio':medianRatio,'nonregression_gate':guard});}
require(usefulCohorts==1,'Prespecified compressed Interactive cohort');final retain=guards&&useful;output.writeAsStringSync('${const JsonEncoder.withIndent('  ').convert({'accepted':112,'measured':96,'preparation':16,'retain':retain,'all_nonregression_gates':guards,'compressed_interactive_memory_gate':useful,'results':results,'samples_sha256':stats.sha('$root/paired-samples.jsonl'),'identities_sha256':stats.sha('$root/paired-identities.json'),'analysis_script_sha256':stats.sha(Platform.script.toFilePath()),'statistics_helper_sha256':stats.sha('$worktree/tools/summarize-adaptive-workers.dart'),'scope':'Public plaintext1GiB add, two source types and Interactive/BulkImport workflows, Auto workers. Whole-process RSS excludes helper agent;100MB write target remains open. No ZIP/PGP or release qualification.'})}\n');print(green('Direct raw cleartext page retention: $retain;112 audited.'));for(final result in results)print(jsonEncode(result));}
